import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Exact WORLD Nature selectors/early capture only; preserve canonical transfer and committed-delete output. */
public final class CompanionNatureMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",NATURE=P+"NativeReturnNatureMaterialAction",H=P+"NativeCompanionNature",TARGET=P+"NativeCompanionTargets",NEG=P+"NativeCompanionNegative";
 static AbstractInsnNode previous(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static MethodInsnNode call(String owner,String name,String desc){return new MethodInsnNode(INVOKESTATIC,owner,name,desc,false);}
 static void members(MethodNode m,MethodInsnNode iterator){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(call(NEG,"members","(Ljava/util/List;L"+PC+";)Ljava/util/List;"));m.instructions.insertBefore(iterator,add);}
 static void patch(ClassNode c){
  if(c.name.equals(P+"NativeSummonGroundTransfer$Stage")){int ports=0;for(var m:c.methods)if(m.name.equals("deletion"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(P+"GameHub")&&v.name.equals("classicWorldMembers")){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(call(H,"deletionOwners","(Ljava/util/List;L"+c.name+";)Ljava/util/List;"));m.instructions.insert(v,add);ports++;}if(ports!=1)throw new AssertionError("World committed-deletion owner census port");return;}
  if(c.name.equals(NATURE)){int roots=0,iterators=0,snapshots=0;for(var m:new ArrayList<>(c.methods)){
   if(Set.of("dispatch","cast","admit").contains(m.name)){String name=m.name;var w=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.name="nativeSceneOriginal"+Character.toUpperCase(name.charAt(0))+name.substring(1);int count=name.equals("dispatch")?3:name.equals("cast")?4:5;for(int i=0;i<count;i++)w.instructions.add(new VarInsnNode(name.equals("cast")&&i==3||name.equals("admit")&&i>=2?ILOAD:ALOAD,i));w.instructions.add(call(H,name,m.desc));w.instructions.add(new InsnNode(name.equals("admit")?IRETURN:RETURN));c.methods.add(w);roots++;}
   if(m.name.equals("target"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v){if(v.owner.equals("java/util/List")&&v.name.equals("iterator")&&previous(v) instanceof VarInsnNode list&&list.var==5){members(m,v);iterators++;}if(v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){m.instructions.insertBefore(v,new VarInsnNode(ALOAD,0));m.instructions.set(v,call(TARGET,"snapshots","(L"+PC+";L"+PC+";)Ljava/util/List;"));snapshots++;}}
  }if(roots!=3||iterators!=1||snapshots!=1)throw new AssertionError("Nature ingress ports "+roots+" "+iterators+" "+snapshots);return;}
  int roots=0,iterators=0,snapshots=0,gates=0;for(var m:c.methods)if(m.name.equals("nativeMaterialReturnNatureBody")){roots++;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v){
   if(v.owner.equals("java/util/List")&&v.name.equals("iterator")&&previous(v) instanceof VarInsnNode list&&list.var==12){members(m,v);iterators++;}
   if(v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){if(!(previous(v) instanceof VarInsnNode owner&&owner.var==14))throw new AssertionError("Nature body owner slot");m.instructions.insertBefore(v,new VarInsnNode(ALOAD,0));m.instructions.set(v,call(TARGET,"snapshots","(L"+PC+";L"+PC+";)Ljava/util/List;"));snapshots++;}
   if(v.owner.equals(PC)&&v.name.equals("sameClassicWorldMap")&&previous(v) instanceof VarInsnNode owner&&owner.var==9){m.instructions.set(v,call(TARGET,"same","(L"+PC+";L"+PC+";)Z"));gates++;}
  }}if(roots!=1||iterators!=1||snapshots!=1||gates!=1)throw new AssertionError("Nature WORLD ports "+roots+" "+iterators+" "+snapshots+" "+gates);
 }
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){for(var name:List.of(PC,NATURE,P+"NativeSummonGroundTransfer$Stage")){var c=read(j,name);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(name+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var candidate=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(candidate,name))))throw new AssertionError(name);}}}System.out.println("PASS exact Nature selectors/capture/admission and actor-scene deletion census; original transfer, canonical bag, deletion transaction and BATTLE/player predicates retained");}
}
